async function assertIndependentSeller(sellerUserId) {
  const userSnap = await getDb27().collection("users").doc(sellerUserId).get();
  if (!userSnap.exists) {
    throw new Error("Vendedor no encontrado");
  }
  const user = userSnap.data() || {};
  if (user.role !== "seller") {
    throw new Error("El usuario no es un vendedor");
  }
  if (user.status === "suspended" || user.status === "cancelled") {
    throw new Error("El vendedor no est\xE1 activo");
  }
  const tenantId = String(user.tenantId || "").trim();
  if (!tenantId) {
    throw new Error("El vendedor no tiene tenant asociado");
  }
  const tenantSnap = await getDb27().collection("tenants").doc(tenantId).get();
  if (!tenantSnap.exists) {
    throw new Error("Tenant del vendedor no encontrado");
  }
  const tenant = tenantSnap.data() || {};
  if (tenant.type !== "seller") {
    throw new Error("Solo se pueden invitar vendedores con cuenta independiente (tenant seller)");
  }
  const ownerId = String(tenant.ownerId || "").trim();
  if (ownerId && ownerId !== sellerUserId) {
    throw new Error("Este vendedor no es titular de su cuenta; no puede vincularse desde aqu\xED");
  }
  if (user.dealerId) {
    throw new Error("Este vendedor ya est\xE1 vinculado a un concesionario");
  }
  return {
    userId: sellerUserId,
    email: String(user.email || ""),
    name: String(user.name || "Vendedor"),
    tenantId,
    dealerId: user.dealerId
  };
}
