    ...extras.length ? [`Empleos adicionales: ${formatMoney(extras.reduce((s, j) => s + (j.monthlyIncome || 0), 0))}`] : [],
    ...other.length ? [`Otros ingresos: ${formatMoney(other.reduce((s, o) => s + (o.monthlyAmount || 0), 0))}`] : [],
    ...request.spouseInfo?.monthlyIncome ? [`C\xF3nyuge: ${formatMoney(request.spouseInfo.monthlyIncome)}`] : [],
